N = '"Nordic"'
AE = '"Aesir"'
NR = '"Nordic Relic"'
def each(n): return ' Sólo puedes usar cada efecto de "%s" una vez por turno.' % n
def eachf(n): return ' Sólo puedes usar cada uno de los siguientes efectos de "%s" una vez por turno.' % n
def revive(tuner, then): return 'Una vez por turno, durante la End Phase, si esta carta boca arriba que controlabas fue destruida por una carta de tu adversario y mandada a tu Cementerio este turno: puedes desterrar 1 Cantante "%s" de tu Cementerio; Invoca esta carta de Modo Especial. %s' % (tuner, then)
OPP = 'No puede ser Invocada de Modo Normal ni Colocada. Primero debe ser Invocada de Modo Especial (desde tu mano) en el Campo de tu adversario en Posición de Defensa'
NOAE = ' Si no hay un monstruo ' + AE + ' en el Campo, destruye esta carta.'
ES = {
"Dverg of the Nordic Alfar": 'Después de que Invoques de Modo Normal esta carta, puedes Invocar de Modo Normal 1 monstruo ' + N + ' durante tu Main Phase este turno, además de tu Invocación Normal o Colocación. (Sólo puedes obtener este efecto una vez por turno.) Si esta carta boca arriba en el Campo es mandada al Cementerio: selecciona 1 carta ' + NR + ' en tu Cementerio; añade ese objetivo a tu mano.',
"Fenrir the Nordic Wolf": OPP + ' durante tu Main Phase 2, mientras haya un monstruo ' + AE + ' en el Campo.' + NOAE + ' Al inicio de tu Battle Phase: cambia todos los monstruos en Posición de Defensa que controlas a Posición de Ataque boca arriba. Ambos jugadores reciben todo el daño de batalla de los ataques que involucren a esta carta.',
"Mara of the Nordic Alfar": 'Al usar esta carta como Material de Sincronía, los otros Materiales de Sincronía deben ser 2 monstruos ' + N + ' de tu mano.',
"Mimir of the Nordic Ascendant": 'Una vez por turno, al inicio de tu Standby Phase, si controlas un monstruo ' + N + ' y esta carta está en tu Cementerio: puedes mandar 1 Mágica de tu mano al Cementerio; Invoca esta carta de Modo Especial.',
"Valkyrie of the Nordic Ascendant": '(Esta carta no se trata como una carta "Valkyrie".)\nCuando esta carta sea Invocada de Modo Normal, si tu adversario controla un monstruo y tú no controlas otras cartas: puedes desterrar 2 monstruos ' + N + ' de tu mano; Invoca de Modo Especial 2 "Einherjar Tokens" (Tipo Guerrero/TIERRA/Nivel 4/ATK 1000/DEF 1000) en Posición de Defensa.',
"Nordic Beast Gullinbursti": 'Para una Invocación por Sincronía, puedes usar esta carta en lugar de cualquier 1 Cantante ' + N + '.' + eachf("Nordic Beast Gullinbursti") + ' Si esta carta es Invocada de Modo Normal o Especial: puedes Invocar de Modo Especial 1 monstruo ' + N + ' de tu mano. Puedes seleccionar 1 monstruo ' + N + ' en tu Cementerio, excepto "Nordic Beast Gullinbursti"; añádelo a tu mano.',
"Tanngnjostr of the Nordic Beasts": 'Cuando un monstruo que controlas sea destruido en batalla y mandado al Cementerio: puedes Invocar esta carta de Modo Especial desde tu mano. Una vez por turno, cuando esta carta en Posición de Defensa en el Campo sea cambiada a Posición de Ataque boca arriba: puedes Invocar de Modo Especial 1 monstruo "Nordic Beast" de tu Deck en Posición de Defensa, excepto "Tanngnjostr of the Nordic Beasts".',
"Tanngrisnir of the Nordic Beasts": 'Si esta carta es destruida en batalla y mandada al Cementerio: Invoca de Modo Especial 2 "Nordic Beast Tokens" (Tipo Bestia/TIERRA/Nivel 3/ATK 0/DEF 0).',
"Alviss of the Nordic Alfar": 'Si sólo esta carta es desterrada por el efecto de un Monstruo de Enlace ' + N + ': puedes mandar al Cementerio 1 monstruo ' + N + ' que controles y 2 monstruos ' + N + ' de tu Deck, cuyos Niveles sumen 10 y, después, Invocar de Modo Especial 1 monstruo ' + AE + ' de tu Extra Deck. Si uno o más monstruos ' + AE + ' en tu posesión son mandados a tu Cementerio por tu adversario, excepto en batalla: puedes desterrar esta carta de tu Cementerio; Invoca de Modo Especial 1 monstruo ' + AE + ' de tu Extra Deck, con un nombre distinto al de las cartas en tu Cementerio. Sólo puedes usar este efecto de "Alviss of the Nordic Alfar" una vez por Duelo.',
"Garmr of the Nordic Beasts": 'Si esta carta combate con un monstruo de Nivel 4 o menor, después del cálculo de daño: puedes devolver ese monstruo a la mano.',
"Guldfaxe of the Nordic Beasts": 'Si tu adversario controla un Monstruo de Sincronía y tú no controlas monstruos, puedes Invocar esta carta de Modo Especial (desde tu mano).',
"Ljosalf of the Nordic Alfar": 'Cuando esta carta sea Invocada de Modo Normal: puedes seleccionar 1 monstruo boca arriba que controles, excepto esta carta; Invoca de Modo Especial 1 monstruo ' + N + ' de tu mano con un Nivel menor o igual que el Nivel de ese monstruo boca arriba.',
"Nordic Smith Ivaldi": 'Si controlas un monstruo ' + AE + ' o ' + N + ': puedes Invocar esta carta de Modo Especial desde tu mano. Si esta carta es Invocada de Modo Normal o Especial: puedes añadir a tu mano 1 carta ' + NR + ' de tu Deck.' + each("Nordic Smith Ivaldi"),
"Tyr of the Nordic Champions": 'Los monstruos de tu adversario no pueden elegir como objetivo de ataque monstruos ' + N + ', excepto "Tyr of the Nordic Champions". Si no hay otro monstruo ' + N + ' en el Campo, destruye esta carta.',
"Vanadis of the Nordic Ascendant": 'Para una Invocación por Sincronía, puedes usar esta carta en lugar de cualquier 1 Cantante ' + N + '. Si esta carta es usada como Material de Sincronía, todos los demás Materiales de Sincronía deben ser monstruos ' + N + '. Una vez por turno: puedes mandar al Cementerio 1 monstruo ' + N + ' de tu Deck; el Nivel de esta carta pasa a ser el Nivel de ese monstruo, hasta el final de este turno.',
"Svartalf of the Nordic Alfar": 'Cuando esta carta sea Invocada de Modo Normal: puedes seleccionar 1 monstruo ' + N + ' en tu Cementerio; añade ese objetivo a tu mano.',
"Jormungardr the Nordic Serpent": OPP + ', mientras haya un monstruo ' + AE + ' en el Campo.' + NOAE + ' Una vez mientras esté boca arriba en el Campo, si esta carta boca arriba en Posición de Defensa que controlas es cambiada a Posición de Ataque boca arriba: recibes 3000 de daño.',
"Gotterdammerung": 'Selecciona 1 monstruo ' + AE + ' que controles; dale el control de ese monstruo a tu adversario. Durante la próxima End Phase de tu adversario, destruye ese monstruo y, si lo haces, destierra todas las cartas que controle tu adversario.',
"March Towards Ragnarok": 'Selecciona 1 monstruo ' + AE + ' que controles; hasta el final de este turno, sus efectos quedan negados y, además, ese monstruo boca arriba no es afectado por los efectos de otras Mágicas/Trampas.',
"Nordic Relic Draupnir": 'Equipa sólo a un monstruo ' + AE + ' o ' + N + '. Gana 800 ATK. Si esta carta boca arriba en el Campo es destruida por un efecto de carta: puedes añadir a tu mano 1 carta ' + NR + ' de tu Deck.',
"Nordic Relic Hlidskjalf": 'Invoca de Modo Especial 1 monstruo ' + N + ' de tu Deck, pero no puedes Invocar de Modo Especial monstruos desde el Extra Deck, excepto monstruos ' + AE + ', mientras ese monstruo esté boca arriba en el Campo. Puedes desterrar esta carta de tu Cementerio; añade a tu mano 1 monstruo ' + N + ' de tu Deck y, después, baraja 1 carta de tu mano en el Deck. Sólo puedes usar 1 efecto de "Nordic Relic Hlidskjalf" por turno, y sólo una vez ese turno.',
"The Nordic Lights": 'Los monstruos ' + N + ' en el Campo no pueden ser destruidos en batalla. Si esta carta en el Campo es destruida: destruye todos los monstruos ' + N + ' en el Campo.',
"Loki, Lord of the Aesir": '1 Cantante "Nordic Alfar" + 2 o más monstruos que no sean Cantantes\nUna vez por turno, cuando tu adversario active una Carta Mágica/de Trampa durante tu Battle Phase (Efecto Rápido): puedes negar la activación y, si lo haces, destrúyela. ' + revive("Nordic Alfar", 'Cuando sea Invocada de esta forma: puedes seleccionar 1 Trampa en tu Cementerio; añade ese objetivo a tu mano.'),
"Odin, Father of the Aesir": '1 Cantante "Nordic Ascendant" + 2 o más monstruos que no sean Cantantes\nUna vez por turno: puedes hacer que esta carta no sea afectada por los efectos de Mágicas/Trampas hasta el final de este turno. ' + revive("Nordic Ascendant", 'Cuando sea Invocada de esta forma: puedes robar 1 carta.'),
"Thor, Lord of the Aesir": '1 Cantante "Nordic Beast" + 2 o más monstruos que no sean Cantantes\nUna vez por turno: puedes negar los efectos de todos los monstruos boca arriba que controle tu adversario en ese momento, hasta el final de este turno. ' + revive("Nordic Beast", 'Cuando lo hagas: puedes infligir 800 de daño a tu adversario.'),
"Divine Relic Mjollnir": 'Selecciona 1 monstruo ' + AE + ' que controles; puede realizar un segundo ataque durante cada Battle Phase este turno.',
"Gleipnir, the Fetters of Fenrir": 'Añade a tu mano 1 monstruo ' + N + ' de tu Deck.',
"Nordic Relic Brisingamen": 'Selecciona 1 monstruo boca arriba que controles y 1 monstruo boca arriba que controle tu adversario; el ATK del primer objetivo pasa a ser igual al ATK original del segundo objetivo, hasta el final de este turno.',
"Nordic Relic Gungnir": 'Destierra 1 monstruo ' + AE + ' o ' + N + ' que controles y, después, selecciona 1 carta en el Campo; destrúyela y, además, durante tu 2ª End Phase después de la activación, devuelve al Campo en Posición de Ataque boca arriba el monstruo que desterraste para activar esta carta.',
"Nordic Relic Laevateinn": 'Selecciona 1 monstruo boca arriba en el Campo que haya destruido un monstruo en batalla este turno; destrúyelo. No se pueden activar cartas ni efectos en respuesta a la activación de esta carta.',
"Nordic Relic Megingjord": 'Selecciona 1 monstruo ' + AE + ' o ' + N + ' que controles; su ATK/DEF pasan a ser el doble de su ATK/DEF originales, hasta el final de este turno, pero no puede atacar directamente a tu adversario este turno.',
"Nordic Relic Svalinn": 'Si controlas un monstruo ' + AE + ': puedes negar los efectos de todas las cartas boca arriba que controle tu adversario en ese momento, hasta el final de este turno. Puedes Sacrificar 1 monstruo ' + N + ' y, después, seleccionar 1 monstruo ' + AE + ' en tu Cementerio; Invócalo de Modo Especial. Sólo puedes usar 1 efecto de "Nordic Relic Svalinn" por turno, y sólo una vez ese turno.',
"Odin's Eye": 'Una vez por turno, durante la Standby Phase de cada jugador: puedes seleccionar 1 monstruo ' + AE + ' que controles; niega sus efectos hasta el final de este turno y, si lo haces, mira todas las cartas de la mano de tu adversario y todas las cartas Colocadas que controla. Tu adversario no puede activar cartas ni efectos en respuesta a la activación de este efecto.',
"Solemn Authority": 'Activa esta carta seleccionando 1 monstruo ' + AE + ' que controles; no puede ser seleccionado por los efectos de otras cartas mientras esta carta esté en el Campo. Manda esta carta al Cementerio durante tu 2ª Standby Phase después de la activación.',
}
